// Mixed provenance: one local transcript anchor (present) + one foreign/pulled
// anchor (session id only). Nothing was deleted. Does the mirror strip it?
func TestReviewProbeMixedProvenance(t *testing.T) {
	opts, repo, _ := vanishedCacheFixture(t)
	runFilelessExport(t, opts, "", true)
	storage, _ := repoStoragePaths(t.Context(), opts.Runner, opts.Env, repo)
	brain := storage.BrainDir
	m, _ := bmanifest.Load(brain)
	rels := map[string]string{}
	for _, s := range m.Sources.Sessions.Sessions {
		rels[s.SessionID] = s.TranscriptPath
	}
	now := opts.Now()
	facts := []factRecord{{ID: "fact:mixed", Kind: factKindDecision, Text: "x", Branch: "main", Origin: "distilled", Status: factStatusActive, CreatedAt: now, UpdatedAt: now,
		Provenance: []factAnchor{{SessionID: "session-alive", Transcript: rels["session-alive"]}, {SessionID: "mem0:abc"}, {SessionID: "teammate-session"}}}}
	if err := factstore.Write(brain, "main", facts); err != nil {
		t.Fatal(err)
	}
	if err := updateFactSourceManifest(brain, now); err != nil {
		t.Fatal(err)
	}
	d, s, err := dropFactsForMissingSessions(brain, now)
	left, _ := factstore.Load(brain, "main")
	t.Logf("deleted=%d stripped=%d err=%v provenance=%+v", d, s, err, left[0].Provenance)
}
EOF
