func TestFactReviewIDStableAcrossInputOrder(t *testing.T) {
	facts := []factRecord{
		{ID: "fact:a", Text: "A", Status: factStatusActive},
		{ID: "fact:b", Text: "B", Status: factStatusActive},
		{ID: "fact:c", Text: "C", Status: factStatusActive},
