func TestInspectRawTextFailsClosedOnUnreadableManifest(t *testing.T) {
	brainDir := writePrivacyFixture(t)
	now := time.Date(2026, 8, 8, 10, 0, 0, 0, time.UTC)
	stones := brainstore.LoadSessionTombstones(brainDir)
	stones.Excluded["secret-sess"] = sessionTombstone{At: now, Reason: "user requested"}
	if err := brainstore.SaveSessionTombstones(brainDir, stones); err != nil {
		t.Fatal(err)
	}

	// With a readable manifest the excluded transcript is skipped by path.
	report, err := inspectBrainRawText(brainDir, "all", privacyCanary, 50)
	if err != nil {
		t.Fatalf("raw inspect with a readable manifest: %v", err)
	}
	for _, match := range report.Matches {
		if strings.Contains(match.Excerpt, privacyCanary) {
			t.Fatalf("excluded transcript leaked with a readable manifest: %+v", match)
		}
	}

	// An unparseable manifest must FAIL the scan, not scan without a guard.
	if err := os.WriteFile(filepath.Join(brainDir, bmanifest.FileName), []byte("{"), 0o600); err != nil {
		t.Fatal(err)
	}
	report, err = inspectBrainRawText(brainDir, "all", privacyCanary, 50)
	if err == nil {
		t.Fatalf("unreadable manifest must fail the raw scan closed; got %d matches", len(report.Matches))
	}
	for _, match := range report.Matches {
		if strings.Contains(match.Excerpt, privacyCanary) {
			t.Fatalf("excluded transcript leaked through an unreadable manifest: %+v", match)
		}
	}
}
func TestShortTermDeltaNonTranscriptBoundBreachPreservesPriorOverlay(t *testing.T) {
	brainDir, _, _ := shortTermFixture(t)
	buildShortTerm(t, brainDir)
	overlayPath := filepath.Join(brainDir, filepath.FromSlash(historyShortTermPath))
	before, err := os.ReadFile(overlayPath)
	if err != nil {
		t.Fatal(err)
	}

	// A VALID policy file that is merely larger than its ceiling, so the
	// refusal can only come from the bound and not from parsing.
	writeSessionTombstoneBytes(t, brainDir, []byte(`{"version":1,"excluded":{}}`+strings.Repeat(" ", 4096)))
	oldMax := base.MaxManifestBytes
	base.MaxManifestBytes = 64
	t.Cleanup(func() { base.MaxManifestBytes = oldMax })

	err = brainstore.WithBrainWriteLock(brainDir, func() error {
		_, buildErr := buildHistoryShortTermLocked(brainDir, time.Now().UTC())
		return buildErr
	})
	requireSessionTombstoneError(t, err, brainstore.StateCorruptCode, brainstore.SessionTombstoneCorrupt)
	if !strings.Contains(err.Error(), "exceeds maximum size") {
		t.Fatalf("the refusal did not come from the ceiling: %v", err)
	}
	after, readErr := os.ReadFile(overlayPath)
	if readErr != nil {
		t.Fatal(readErr)
	}
	if !bytes.Equal(after, before) {
		t.Fatal("a bound-breach refusal republished the overlay; the prior generation must stay byte-identical")
	}
}

